-- Local trade directory from the vik sheet only. Inserted once; later deploys skip this migration.

CREATE TABLE "local_service_categories" (
    "id" UUID NOT NULL,
    "slug" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "sort_order" INTEGER NOT NULL,

    CONSTRAINT "local_service_categories_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "local_service_categories_slug_key" ON "local_service_categories"("slug");

CREATE TABLE "local_service_contacts" (
    "id" UUID NOT NULL,
    "category_id" UUID NOT NULL,
    "name" TEXT NOT NULL,
    "phone" VARCHAR(10) NOT NULL,
    "sort_order" INTEGER NOT NULL,

    CONSTRAINT "local_service_contacts_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "local_service_contacts_category_id_sort_order_idx" ON "local_service_contacts"("category_id", "sort_order");

ALTER TABLE "local_service_contacts"
ADD CONSTRAINT "local_service_contacts_category_id_fkey"
FOREIGN KEY ("category_id") REFERENCES "local_service_categories"("id") ON DELETE CASCADE ON UPDATE CASCADE;


